(window.PM_Q=window.PM_Q||[]).push(["as",{"as1":[{"t":{"si":"කථා වස්තුව","en":"The Story"},"h":{"si":"<div class=\"place\">සැවැත් නුවර · ජේතවනාරාමය<\/div><p><strong>ෂඩ්වර්ගීය භික්ෂූහු<\/strong> <mark><strong>අසම්මුඛව (නැති තැන)<\/strong> සිටි භික්ෂූන්ට <strong>තජ්ජනීය, නියස්ස, පබ්බාජනීය, පටිසාරණීය, උක්ඛේපනීය<\/strong> කර්ම කළහ<\/mark>. අල්පේච්ඡ භික්ෂූහු දොස් කීහ. භාග්‍යවතුන් වහන්සේ \"<strong>අසම්මුඛව කළ කර්ම අධර්ම කර්ම ය<\/strong>\" යි වදාරා, අධිකරණ <strong>සම්මුඛව<\/strong> විසඳිය යුතු බව වදාළහ (චූළවග්ග, සමථක්ඛන්ධකය).<\/p>","en":"<div class=\"place\">Sāvatthī · Jetavana monastery<\/div><p><strong>The group-of-six<\/strong> <mark>carried out <strong>censure, guidance, banishment, reconciliation and suspension<\/strong> acts against monks <strong>who were not present<\/strong><\/mark>. Monks of few wishes complained. The Blessed One declared “<strong>Acts done in absence are illegitimate<\/strong>,” and taught that issues must be settled <strong>face to face<\/strong> (Cūḷavagga, Samatha-khandhaka).<\/p>"}},{"t":{"si":"(අ) අධිකරණ සතර — කඞ්ඛාවිතරණී අනුව","en":"(A) The four kinds of issue — according to the Kaṅkhāvitaraṇī"},"h":{"si":"<p><strong>සත්ත<\/strong> — සමථවල <strong>ගණන<\/strong> යි. <strong>අධිකරණසමථා<\/strong> — <strong>අධිකරණ සංසිඳවන, සන්සුන් කරන<\/strong> බැවින් එසේ කියනු ලැබේ.<\/p><div class=\"scroll\"><table><tr><th>අධිකරණය<\/th><th>අර්ථය<\/th><\/tr><tr><td><strong>විවාදාධිකරණය<\/strong><\/td><td>\"<strong>ධර්මය ය<\/strong>\" හෝ \"<strong>අධර්මය ය<\/strong>\" ආදී <strong>වස්තු දහඅටකින්<\/strong> විවාද කරන භික්ෂූන්ගේ <strong>විවාදය<\/strong><\/td><\/tr><tr><td><strong>අනුවාදාධිකරණය<\/strong><\/td><td><strong>සීල විපත්තියෙන්<\/strong>, හෝ <strong>ආචාර, දිට්ඨි, ආජීව විපත්තියෙන්<\/strong> චෝදනා කරන අයගේ <strong>අනුවාදය — උපවාදය හා චෝදනාව<\/strong><\/td><\/tr><tr><td><strong>ආපත්තාධිකරණය<\/strong><\/td><td>මාතිකාවේ ආ <strong>පහ<\/strong> හා විභංගයේ ආ <strong>දෙක<\/strong> යන <strong>ආපත්ති ස්කන්ධ සත<\/strong> ම<\/td><\/tr><tr><td><strong>කිච්චාධිකරණය<\/strong><\/td><td>සංඝයාගේ <strong>අපලෝකන ආදී කර්ම සතර<\/strong> කිරීම<\/td><\/tr><\/table><\/div>","en":"<p><strong>Satta<\/strong> — <strong>the number<\/strong> of the settlements. <strong>Adhikaraṇasamathā<\/strong> — so called because they <strong>settle and calm issues<\/strong>.<\/p><div class=\"scroll\"><table><tr><th>Issue<\/th><th>Meaning<\/th><\/tr><tr><td><strong>dispute (vivāda)<\/strong><\/td><td>the <strong>dispute<\/strong> of monks arguing on <strong>the eighteen grounds<\/strong>, such as “<strong>this is Dhamma<\/strong>” or “<strong>this is not Dhamma<\/strong>”<\/td><\/tr><tr><td><strong>accusation (anuvāda)<\/strong><\/td><td>the <strong>accusation — reproach and charge<\/strong> — of those accusing of <strong>failure in morality<\/strong>, or <strong>in conduct, view or livelihood<\/strong><\/td><\/tr><tr><td><strong>offence (āpatti)<\/strong><\/td><td><strong>all seven classes of offence<\/strong> — <strong>five<\/strong> in the Mātikā and <strong>two<\/strong> in the Vibhaṅga<\/td><\/tr><tr><td><strong>duty (kicca)<\/strong><\/td><td>carrying out <strong>the four Saṅgha acts<\/strong>, by announcement and the rest<\/td><\/tr><\/table><\/div>"}},{"t":{"si":"(ආ) සම්මුඛතා සතර","en":"(B) The four kinds of presence"},"h":{"si":"<p>සම්මුඛා විනය නම් අධිකරණය සංසිඳෙන විට පවතින මේ <strong>සම්මුඛතා සතර<\/strong> යි:<\/p><div class=\"scroll\"><table><tr><th>සම්මුඛතාව<\/th><th>අර්ථය — කඞ්ඛාවිතරණී අනුව<\/th><\/tr><tr><td><strong>සංඝ සම්මුඛතා<\/strong><\/td><td>කර්මය කරන සංඝයා <strong>සමගිව, සම්මුඛව<\/strong> සිටීම<\/td><\/tr><tr><td><strong>ධම්ම සම්මුඛතා<\/strong><\/td><td>සංසිඳවිය යුතු <strong>වස්තුව සත්‍ය (භූත)<\/strong> වීම<\/td><\/tr><tr><td><strong>විනය සම්මුඛතා<\/strong><\/td><td>සංසිඳවිය යුතු <strong>ආකාරයට ම<\/strong> සංසිඳවීම<\/td><\/tr><tr><td><strong>පුග්ගල සම්මුඛතා<\/strong><\/td><td><strong>විවාද කරන්නා හා විවාද කරනු ලබන්නා<\/strong> — දෙපක්ෂය ම <strong>සම්මුඛව<\/strong> සිටීම<\/td><\/tr><\/table><\/div><p><mark><strong>උබ්බාහිකාවකින්<\/strong> සංසිඳවන විට <strong>සංඝ සම්මුඛතාව<\/strong> නැත<\/mark>; <strong>පුද්ගලයෙකු හෝ ගණයෙකු ඉදිරියේ<\/strong> ඇවැත් දෙසන විට ද <strong>සංඝ සම්මුඛතාව<\/strong> නැත.<\/p>","en":"<p>A face-to-face verdict is <strong>these four kinds of presence<\/strong> when an issue is settled:<\/p><div class=\"scroll\"><table><tr><th>Presence<\/th><th>Meaning — according to the Kaṅkhāvitaraṇī<\/th><\/tr><tr><td><strong>of the Saṅgha<\/strong><\/td><td>the Saṅgha doing the act is <strong>present and united<\/strong><\/td><\/tr><tr><td><strong>of the Dhamma<\/strong><\/td><td>the matter to be settled <strong>is real (bhūta)<\/strong><\/td><\/tr><tr><td><strong>of the Vinaya<\/strong><\/td><td>it is settled <strong>just as it should be settled<\/strong><\/td><\/tr><tr><td><strong>of the individuals<\/strong><\/td><td><strong>the one disputing and the one disputed with<\/strong> — both parties <strong>present<\/strong><\/td><\/tr><\/table><\/div><p><mark>When it is settled <strong>by a referral committee<\/strong>, <strong>presence of the Saṅgha<\/strong> is lacking<\/mark>; when an offence is confessed <strong>before an individual or a group<\/strong>, <strong>presence of the Saṅgha<\/strong> is also lacking.<\/p>"}},{"t":{"si":"(ඇ) සංසිඳවන අධිකරණ","en":"(C) Issues it settles"},"h":{"si":"<p><mark><strong>අධිකරණ සතර ම<\/strong> සම්මුඛා විනය සමඟ සංසිඳේ<\/mark>; <strong>කිච්චාධිකරණය සම්මුඛා විනයෙන් පමණක්<\/strong> සංසිඳේ.<\/p><div class=\"scroll\"><table><tr><th>අධිකරණය<\/th><th>සම්මුඛා විනයෙන් සංසිඳෙන ආකාරය<\/th><\/tr><tr><td><strong>විවාදාධිකරණය<\/strong><\/td><td><strong>උපන් විහාරයේ ම<\/strong>, හෝ වෙනත් තැනකට <strong>යන අතරමඟ<\/strong>, හෝ <strong>ගෙන ගොස් භාර දුන් තැන සංඝයා<\/strong> විසින්, නොහැකි නම් <strong>එහි ම උබ්බාහිකාවට සම්මත භික්ෂූන්<\/strong> විසින් විනිශ්චය කිරීම<\/td><\/tr><tr><td><strong>අනුවාදාධිකරණය<\/strong><\/td><td><strong>චෝදනා කරන්නාගේ හා චෝදනා ලබන්නාගේ<\/strong> වචන අසා, <strong>ඇවතක් නැත්නම් දෙදෙනාට ම සමා කරවා<\/strong>, <strong>ඇත්නම් \"මෙහි මේ ඇවත ය\"<\/strong> යි විනිශ්චය කිරීම<\/td><\/tr><tr><td><strong>ආපත්තාධිකරණය<\/strong><\/td><td>සම්මුඛා විනයෙන් <strong>පමණක්<\/strong> නොසංසිඳේ — <strong>පටිඤ්ඤාතකරණය<\/strong> හෝ <strong>තිණවත්ථාරකය<\/strong> සමඟ ය<\/td><\/tr><tr><td><strong>කිච්චාධිකරණය<\/strong><\/td><td><strong>සම්මුඛා විනයෙන් ම<\/strong><\/td><\/tr><\/table><\/div>","en":"<p><mark><strong>All four issues<\/strong> are settled together with the face-to-face verdict<\/mark>; <strong>duties are settled by the face-to-face verdict alone<\/strong>.<\/p><div class=\"scroll\"><table><tr><th>Issue<\/th><th>How it is settled face to face<\/th><\/tr><tr><td><strong>dispute<\/strong><\/td><td>decided <strong>in the monastery where it arose<\/strong>, or <strong>on the way<\/strong> to another place, or <strong>by the Saṅgha to which it was handed over<\/strong>, or failing that, <strong>by monks authorised there as a referral committee<\/strong><\/td><\/tr><tr><td><strong>accusation<\/strong><\/td><td>hearing <strong>the accuser and the accused<\/strong>, <strong>if there is no offence, having both forgive each other<\/strong>, <strong>if there is, deciding “this is the offence here”<\/strong><\/td><\/tr><tr><td><strong>offence<\/strong><\/td><td><strong>not<\/strong> by the face-to-face verdict <strong>alone<\/strong> — together with <strong>acting on acknowledgement<\/strong> or <strong>covering over with grass<\/strong><\/td><\/tr><tr><td><strong>duty<\/strong><\/td><td><strong>by the face-to-face verdict alone<\/strong><\/td><\/tr><\/table><\/div>"}},{"t":{"si":"(ඈ) විනිශ්චය කරන තැන — පිළිවෙළ","en":"(D) Where it is decided — in order"},"h":{"si":"<div class=\"factors\"><div class=\"fitem\"><b>1<\/b><div>පළමුව <strong>අධිකරණය උපන් ආවාසයේ ම<\/strong> සංඝයා සංසිඳවීමට උත්සාහ කරයි.<\/div><\/div><div class=\"fitem\"><b>2<\/b><div>නොහැකි නම් <strong>වඩා බොහෝ භික්ෂූන් සිටින ආවාසයකට<\/strong> ගෙන යයි; <strong>අතරමඟ දී<\/strong> ද සංසිඳවිය හැකිය.<\/div><\/div><div class=\"fitem\"><b>3<\/b><div>එහි දී <strong>අනන්ත කථා<\/strong> ඇති වී <strong>කිසිවකුගේ කීමේ අර්ථය නොතේරේ<\/strong> නම්, <strong>අංග දහයකින් යුත්<\/strong> භික්ෂූන් <strong>උබ්බාහිකාවට<\/strong> සම්මත කොට ඔවුන් ලවා විනිශ්චය කරවයි.<\/div><\/div><\/div><p><strong>උබ්බාහිකාවට සම්මත කළ යුතු භික්ෂුවගේ අංග දහය (චූළවග්ගය):<\/strong><\/p><div class=\"factors\"><div class=\"fitem\"><b>1<\/b><div><strong>සිල්වත්<\/strong> ය — පාතිමොක්ඛ සංවරයෙන් සංවෘත, ආචාර ගෝචර සම්පන්න, අණුමාත්‍ර වරදෙහි ද භය දක්නා.<\/div><\/div><div class=\"fitem\"><b>2<\/b><div><strong>බහුශ්‍රැත<\/strong> ය — ඇසූ දේ දරන, රැස් කරන.<\/div><\/div><div class=\"fitem\"><b>3<\/b><div><strong>ප්‍රාතිමෝක්ෂ දෙක ම<\/strong> විස්තර වශයෙන් <strong>මනාව උගත්, මනාව විභජනය කළ, සූත්‍ර හා අනුව්‍යඤ්ජන වශයෙන් මනාව විනිශ්චය කළ<\/strong>.<\/div><\/div><div class=\"fitem\"><b>4<\/b><div><strong>විනයයේ ස්ථිර, නොසැලෙන<\/strong>.<\/div><\/div><div class=\"fitem\"><b>5<\/b><div><strong>දෙපක්ෂයට ම<\/strong> හඟවන්නට, දක්වන්නට, බලන්නට, පහදවන්නට <strong>සමර්ථ<\/strong>.<\/div><\/div><div class=\"fitem\"><b>6<\/b><div><strong>අධිකරණය උපදවීමට හා සංසිඳවීමට දක්ෂ<\/strong>.<\/div><\/div><div class=\"fitem\"><b>7<\/b><div><strong>අධිකරණය දන්නා<\/strong>.<\/div><\/div><div class=\"fitem\"><b>8<\/b><div><strong>අධිකරණයේ හේතුව (සමුදය) දන්නා<\/strong>.<\/div><\/div><div class=\"fitem\"><b>9<\/b><div><strong>අධිකරණයේ නිරෝධය දන්නා<\/strong>.<\/div><\/div><div class=\"fitem\"><b>10<\/b><div><strong>අධිකරණ නිරෝධයට යන මඟ දන්නා<\/strong>.<\/div><\/div><\/div>","en":"<div class=\"factors\"><div class=\"fitem\"><b>1<\/b><div>First the Saṅgha <strong>in the residence where the issue arose<\/strong> tries to settle it.<\/div><\/div><div class=\"fitem\"><b>2<\/b><div>If it cannot, the issue is taken <strong>to a residence with more monks<\/strong>; it may also be settled <strong>on the way<\/strong>.<\/div><\/div><div class=\"fitem\"><b>3<\/b><div>If there <strong>endless talk<\/strong> arises and <strong>the meaning of what anyone says cannot be understood<\/strong>, monks <strong>with ten qualities<\/strong> are authorised as <strong>a referral committee (ubbāhikā)<\/strong> to decide it.<\/div><\/div><\/div><p><strong>The ten qualities of a monk for the referral committee (Cūḷavagga):<\/strong><\/p><div class=\"factors\"><div class=\"fitem\"><b>1<\/b><div><strong>Virtuous<\/strong> — restrained by the Pātimokkha, of good conduct and resort, seeing danger in the slightest fault.<\/div><\/div><div class=\"fitem\"><b>2<\/b><div><strong>Learned<\/strong> — retaining and storing what he has heard.<\/div><\/div><div class=\"fitem\"><b>3<\/b><div>Has <strong>both Pātimokkhas<\/strong> <strong>well learnt in detail, well analysed, well decided by rule and detail<\/strong>.<\/div><\/div><div class=\"fitem\"><b>4<\/b><div><strong>Firm in the Vinaya, not to be shaken<\/strong>.<\/div><\/div><div class=\"fitem\"><b>5<\/b><div><strong>Able<\/strong> to make <strong>both parties<\/strong> understand, see, look and be reconciled.<\/div><\/div><div class=\"fitem\"><b>6<\/b><div><strong>Skilled at raising and settling issues<\/strong>.<\/div><\/div><div class=\"fitem\"><b>7<\/b><div><strong>Knows the issue<\/strong>.<\/div><\/div><div class=\"fitem\"><b>8<\/b><div><strong>Knows its origin<\/strong>.<\/div><\/div><div class=\"fitem\"><b>9<\/b><div><strong>Knows its cessation<\/strong>.<\/div><\/div><div class=\"fitem\"><b>10<\/b><div><strong>Knows the way to its cessation<\/strong>.<\/div><\/div><\/div>"}},{"t":{"si":"(ඉ) ධාර්මික හා අධාර්මික සම්මුඛා විනය","en":"(E) Legitimate and illegitimate face-to-face settlement"},"h":{"si":"<div class=\"scroll\"><table><tr><th>කවුරුන් කවුරුන් හඟවයි ද<\/th><th>ප්‍රතිඵලය<\/th><\/tr><tr><td><strong>අධර්මවාදී<\/strong> පුද්ගලයෙක් / බොහෝ දෙනෙක් / සංඝයා, <strong>ධර්මවාදී<\/strong> පුද්ගලයෙකු / බොහෝ දෙනෙකු / සංඝයා \"<strong>මෙය ධර්මය, මෙය විනය, මෙය ශාස්තෘ ශාසනය; මෙය ගන්න, මෙය රුචි කරන්න<\/strong>\" යි හඟවා, සංසිඳවයි (<strong>කෘෂ්ණ පක්ෂ නවකය<\/strong>)<\/td><td><strong>අධර්මයෙන්<\/strong> සංසිඳුණි — <strong>සම්මුඛා විනයට සමාන ව්‍යාජයක්<\/strong><\/td><\/tr><tr><td><strong>ධර්මවාදී<\/strong> පුද්ගලයෙක් / බොහෝ දෙනෙක් / සංඝයා, <strong>අධර්මවාදී<\/strong> පුද්ගලයෙකු / බොහෝ දෙනෙකු / සංඝයා එසේ හඟවා සංසිඳවයි (<strong>ශුක්ල පක්ෂ නවකය<\/strong>)<\/td><td><strong>ධර්මයෙන්<\/strong> සංසිඳුණි — <strong>සම්මුඛා විනයෙන්<\/strong><\/td><\/tr><\/table><\/div>","en":"<div class=\"scroll\"><table><tr><th>Who persuades whom<\/th><th>Result<\/th><\/tr><tr><td><strong>one who speaks against the Dhamma<\/strong> — an individual / several / a Saṅgha — persuades <strong>one who speaks Dhamma<\/strong> — an individual / several / a Saṅgha — “<strong>This is Dhamma, this is Vinaya, this is the Teacher’s instruction; take this, approve this<\/strong>,” and settles it (<strong>the dark nine<\/strong>)<\/td><td>settled <strong>illegitimately<\/strong> — <strong>a counterfeit of the face-to-face verdict<\/strong><\/td><\/tr><tr><td><strong>one who speaks Dhamma<\/strong> — an individual / several / a Saṅgha — persuades <strong>one who speaks against the Dhamma<\/strong> thus and settles it (<strong>the bright nine<\/strong>)<\/td><td>settled <strong>legitimately<\/strong> — <strong>by the face-to-face verdict<\/strong><\/td><\/tr><\/table><\/div>"}},{"t":{"si":"(ඊ) නැවත ඇවිස්සීම","en":"(F) Reopening"},"h":{"si":"<p>ධර්මයෙන් සංසිඳවූ අධිකරණය \"<strong>නැවත කළ යුතුය<\/strong>\" යි දැන දැන ඇවිස්සීම <strong>පාචිත්තිය 63 (උක්කෝටන)<\/strong> ය.<\/p>","en":"<p>Knowingly reopening an issue legitimately settled, saying “<strong>it must be done again<\/strong>,” is <strong>pācittiya 63 (reopening)<\/strong>.<\/p>"}}],"as2":[{"t":{"si":"කථා වස්තුව","en":"The Story"},"h":{"si":"<div class=\"place\">රජගහ නුවර · වේළුවනය කලන්දක නිවාපය<\/div><p>ආයුෂ්මත් <strong>දබ්බ මල්ලපුත්ත<\/strong> තෙරුන් <strong>සත් හැවිරිදි වියේ දී රහත්<\/strong> වූහ. සංඝයාට සේවය කිරීමට සිතා, <strong>සංඝයා විසින් සෙනසුන් පනවන්නා හා බත් උද්දේශකයා ලෙස සම්මත<\/strong> කරනු ලැබූහ. රාත්‍රියේ පැමිණි භික්ෂූන්ට <strong>ඇඟිල්ල දල්වා (තේජෝ ධාතු සමාපත්තියෙන්)<\/strong> ආලෝකය දෙමින් සෙනසුන් පෙන්වූහ.<\/p><p><strong>මෙත්තිය-භූමජක<\/strong> භික්ෂූහු <strong>නවක ද අල්පපුණ්‍ය ද<\/strong> වූ බැවින් සංඝයාගේ <strong>ලාමක සෙනසුන් හා ලාමක බත්<\/strong> ඔවුන්ට ලැබිණ. <strong>කල්‍යාණභත්තික ගෘහපතියාගේ<\/strong> ප්‍රණීත දානය බලාපොරොත්තු වූ දිනයේ ද ලාමක බත ලැබී, <mark>කිපී <strong>මෙත්තියා භික්ෂුණිය<\/strong> ලවා දබ්බ තෙරුන්ට <strong>\"මා දූෂණය කළේය\"<\/strong> යි <strong>අමූලක සීල විපත්තියකින්<\/strong> චෝදනා කරවූහ<\/mark>.<\/p><p>භාග්‍යවතුන් වහන්සේ සංඝයා රැස් කොට \"<strong>දබ්බ, මේ භික්ෂුණිය කියන්නාක් මෙන් කළ බවක් සිහි වේ ද?<\/strong>\" යි ඇසූ කල්හි, තෙරුන් \"<strong>ස්වාමීනි, භාග්‍යවතුන් වහන්සේ මා දන්නා සේක<\/strong>\" යි කියා, \"<strong>ස්වාමීනි, සිහිනයෙන් වත් මෛථුනය සේවනය කළ බවක් නොදනිමි<\/strong>\" යි කීහ. භික්ෂුණිය <strong>නාසනය<\/strong> කරනු ලැබූවාය; මෙත්තිය-භූමජකයෝ තමන් ඇය පෙළඹවූ බව පිළිගත්හ. එවිට භාග්‍යවතුන් වහන්සේ <strong>සතිවෙපුල්ලප්පත්ත (සිහිය විපුල බවට පත්)<\/strong> දබ්බ තෙරුන්ට <strong>සතිවිනය දීමට<\/strong> අනුදැන වදාළහ.<\/p>","en":"<div class=\"place\">Rājagaha · Veḷuvana, the squirrels' feeding place<\/div><p>Ven. <strong>Dabba the Mallian<\/strong> <strong>became an arahant at seven years of age<\/strong>. Wishing to serve the Saṅgha, he was <strong>authorised by the Saṅgha as assigner of lodgings and allocator of meals<\/strong>. For monks arriving at night he showed the lodgings <strong>by the light of his blazing finger (attaining the fire element)<\/strong>.<\/p><p><strong>The Mettiya-Bhūmajaka monks<\/strong>, being <strong>junior and of little merit<\/strong>, received <strong>the Saṅgha’s poorer lodgings and poorer meals<\/strong>. On the day they expected <strong>the householder Kalyāṇabhattika’s<\/strong> fine meal, they again received a poor one, and <mark>in anger had <strong>the nun Mettiyā<\/strong> accuse Dabba — “<strong>He has violated me<\/strong>” — with <strong>a groundless failure in morality<\/strong><\/mark>.<\/p><p>The Blessed One convened the Saṅgha and asked, “<strong>Dabba, do you remember having done what this nun says?<\/strong>” He replied, “<strong>Venerable sir, the Blessed One knows me<\/strong>,” and, “<strong>Venerable sir, I do not recall indulging in sexual intercourse even in a dream.<\/strong>” The nun was <strong>expelled<\/strong>; the Mettiya-Bhūmajakas admitted they had incited her. The Blessed One then allowed <strong>a verdict of mindfulness<\/strong> to be given to Dabba, <strong>who had reached fullness of mindfulness (sativepullappatta)<\/strong>.<\/p>"}},{"t":{"si":"(අ) විස්තරය — කඞ්ඛාවිතරණී අනුව","en":"(A) Explanation — according to the Kaṅkhāvitaraṇī"},"h":{"si":"<p><mark><strong>ක්ෂීණාශ්‍රවයෙකුට (රහතන් වහන්සේ වැනි පිරිසිදු භික්ෂුවකට)<\/strong> <strong>අමූලක සීල විපත්තියකින්<\/strong> චෝදනා කරන විට<\/mark>, ඔහු <strong>සතිවිනය ඉල්ලුවහොත්<\/strong>, සංඝයා <strong>ඤත්තිචතුත්ථ කර්මයෙන්<\/strong> සතිවිනය දෙයි.<\/p><p><mark>සතිවිනය දුන් පසු <strong>ඒ පුද්ගලයා කෙරෙහි කිසිවකුගේ චෝදනාවක් නොනැගේ<\/strong><\/mark>.<\/p>","en":"<p><mark>When <strong>one whose taints are destroyed (a pure monk such as an arahant)<\/strong> is accused <strong>with a groundless failure in morality<\/strong><\/mark>, and he <strong>asks for a verdict of mindfulness<\/strong>, the Saṅgha gives it <strong>by a motion-and-three-announcements act<\/strong>.<\/p><p><mark>Once the verdict of mindfulness is given, <strong>no one’s accusation against that person takes hold<\/strong><\/mark>.<\/p>"}},{"t":{"si":"(ආ) සංසිඳවන අධිකරණ","en":"(B) Issues it settles"},"h":{"si":"<div class=\"scroll\"><table><tr><th>අධිකරණය<\/th><th>ආකාරය<\/th><\/tr><tr><td><strong>අනුවාදාධිකරණය<\/strong><\/td><td><strong>සම්මුඛා විනයෙන් හා සතිවිනයෙන්<\/strong> සංසිඳේ<\/td><\/tr><\/table><\/div>","en":"<div class=\"scroll\"><table><tr><th>Issue<\/th><th>How<\/th><\/tr><tr><td><strong>accusation<\/strong><\/td><td>settled <strong>by the face-to-face verdict and the verdict of mindfulness<\/strong><\/td><\/tr><\/table><\/div>"}},{"t":{"si":"(ඇ) දෙන ආකාරය","en":"(C) How it is given"},"h":{"si":"<div class=\"factors\"><div class=\"fitem\"><b>1<\/b><div>චෝදනා ලැබූ භික්ෂුව <strong>සංඝයා වෙත ගොස්<\/strong>, <strong>උතුරු සළුව ඒකාංශ කොට<\/strong>, <strong>වැඩිමහල් භික්ෂූන්ගේ පා වැඳ<\/strong>, <strong>උක්කුටිකව හිඳ<\/strong>, <strong>ඇඳිලි බැඳ<\/strong> — \"<strong>ස්වාමීනි, මොවුහු මට අමූලක සීල විපත්තියකින් චෝදනා කරති; සිහිය විපුල බවට පත් මම සංඝයාගෙන් සතිවිනය ඉල්ලමි<\/strong>\" යි <strong>තෙවරක්<\/strong> ඉල්ලයි.<\/div><\/div><div class=\"fitem\"><b>2<\/b><div><strong>ව්‍යක්ත, ප්‍රතිබල<\/strong> භික්ෂුවක් <strong>ඤත්තියක් හා අනුස්සාවන තුනකින්<\/strong> (ඤත්තිචතුත්ථ කර්මයෙන්) සංඝයාට දන්වයි.<\/div><\/div><div class=\"fitem\"><b>3<\/b><div>\"<strong>සංඝයා විසින් සතිවිනය දෙන ලදී<\/strong>\" යි ධාරණය කරයි.<\/div><\/div><\/div>","en":"<div class=\"factors\"><div class=\"fitem\"><b>1<\/b><div>The accused monk <strong>goes to the Saṅgha<\/strong>, <strong>arranges his upper robe over one shoulder<\/strong>, <strong>pays respect at the feet of the senior monks<\/strong>, <strong>squats<\/strong>, <strong>raises his joined palms<\/strong> and asks <strong>three times<\/strong>: “<strong>Venerable sirs, these monks accuse me with a groundless failure in morality; having reached fullness of mindfulness, I ask the Saṅgha for a verdict of mindfulness.<\/strong>”<\/div><\/div><div class=\"fitem\"><b>2<\/b><div><strong>A competent, capable<\/strong> monk informs the Saṅgha <strong>with a motion and three proclamations<\/strong> (a motion-and-three-announcements act).<\/div><\/div><div class=\"fitem\"><b>3<\/b><div>He records: “<strong>The verdict of mindfulness has been given by the Saṅgha.<\/strong>”<\/div><\/div><\/div>"}},{"t":{"si":"(ඈ) ධාර්මික සතිවිනය දානයේ අංග පහ","en":"(D) Five factors of a legitimate verdict of mindfulness"},"h":{"si":"<div class=\"factors\"><div class=\"fitem\"><b>1<\/b><div>භික්ෂුව <strong>පිරිසිදු, ඇවැත් රහිත<\/strong> ය.<\/div><\/div><div class=\"fitem\"><b>2<\/b><div><strong>ඔහුට චෝදනා කරති<\/strong>.<\/div><\/div><div class=\"fitem\"><b>3<\/b><div>ඔහු <strong>ඉල්ලයි<\/strong>.<\/div><\/div><div class=\"fitem\"><b>4<\/b><div>සංඝයා <strong>ධර්මයෙන්<\/strong> දෙයි.<\/div><\/div><div class=\"fitem\"><b>5<\/b><div>සංඝයා <strong>සමගිව<\/strong> දෙයි.<\/div><\/div><\/div>","en":"<div class=\"factors\"><div class=\"fitem\"><b>1<\/b><div>The monk is <strong>pure, without offence<\/strong>.<\/div><\/div><div class=\"fitem\"><b>2<\/b><div><strong>They accuse him<\/strong>.<\/div><\/div><div class=\"fitem\"><b>3<\/b><div>He <strong>asks for it<\/strong>.<\/div><\/div><div class=\"fitem\"><b>4<\/b><div>The Saṅgha gives it <strong>legitimately<\/strong>.<\/div><\/div><div class=\"fitem\"><b>5<\/b><div>The Saṅgha gives it <strong>in unity<\/strong>.<\/div><\/div><\/div>"}}],"as3":[{"t":{"si":"කථා වස්තුව","en":"The Story"},"h":{"si":"<div class=\"place\">රජගහ නුවර · වේළුවනය කලන්දක නිවාපය<\/div><p><strong>ගග්ග<\/strong> නම් භික්ෂුවක් <mark><strong>උමතු වී, සිත විපරීත වී<\/strong>, බොහෝ <strong>ශ්‍රමණයෙකුට නොගැළපෙන<\/strong> දේ කීය, කළේය<\/mark>. පසුව සුවය ලත් ඔහුට භික්ෂූහු \"<strong>ආයුෂ්මත, මෙබඳු ඇවතකට පැමිණි බව සිහි වේ ද?<\/strong>\" යි චෝදනා කළහ. ඔහු \"<strong>ඇවැත්නි, මම උමතු වීමි; උමතුවෙන් මා විසින් එය කරන ලදී; එය මට සිහි නොවේ<\/strong>\" යි කීව ද ඔවුහු නැවත නැවත චෝදනා කළහ. භාග්‍යවතුන් වහන්සේ <strong>අමූළ්හ වූ (දැන් මුළා නොවූ)<\/strong> ගග්ගට <strong>අමූළ්හවිනය දීමට<\/strong> අනුදැන වදාළහ.<\/p>","en":"<div class=\"place\">Rājagaha · Veḷuvana, the squirrels' feeding place<\/div><p>A monk named <strong>Gagga<\/strong> <mark><strong>went insane, his mind deranged<\/strong>, and did and said much <strong>unbecoming to an ascetic<\/strong><\/mark>. After he recovered, monks accused him: “<strong>Venerable, do you remember committing such an offence?<\/strong>” Though he said, “<strong>Friends, I was insane; I did that in my insanity; I don’t remember it<\/strong>,” they kept accusing him. The Blessed One allowed <strong>a verdict of past insanity<\/strong> to be given to Gagga, <strong>now no longer deluded (amūḷha)<\/strong>.<\/p>"}},{"t":{"si":"(අ) විස්තරය — කඞ්ඛාවිතරණී අනුව","en":"(A) Explanation — according to the Kaṅkhāvitaraṇī"},"h":{"si":"<p><mark><strong>උමතු භික්ෂුවක්<\/strong> <strong>උමතුව සිටියදී කළ ශ්‍රමණයෙකුට නොගැළපෙන දේ<\/strong> ගැන \"<strong>සිහි වේ ද?<\/strong>\" යි චෝදනා ලබයි<\/mark>. \"<strong>ඇවැත්නි, උමතු වූ මා එය කළෙමි; මට එය සිහි නොවේ<\/strong>\" යි කීව ද <strong>චෝදනා ලබමින් ම<\/strong> සිටී නම්, <strong>නැවත චෝදනා නොකරනු පිණිස<\/strong> අමූළ්හවිනය ඉල්ලයි. සංඝයා <strong>ඤත්තිචතුත්ථ කර්මයෙන්<\/strong> දෙයි.<\/p><p><mark>අමූළ්හවිනය දුන් පසු <strong>ඒ හේතුව නිසා<\/strong> ඒ පුද්ගලයා කෙරෙහි <strong>කිසිවකුගේ චෝදනාවක් නොනැගේ<\/strong><\/mark>.<\/p>","en":"<p><mark><strong>An insane monk<\/strong> is accused, “<strong>Do you remember?<\/strong>”, about <strong>unbecoming conduct done during his insanity<\/strong><\/mark>. Though he says, “<strong>Friends, I did that when insane; I don’t remember it<\/strong>,” if <strong>the accusations continue<\/strong>, he asks for a verdict of past insanity <strong>so that he will not be accused again<\/strong>. The Saṅgha gives it <strong>by a motion-and-three-announcements act<\/strong>.<\/p><p><mark>Once it is given, <strong>no one’s accusation against him on that account takes hold<\/strong><\/mark>.<\/p>"}},{"t":{"si":"(ආ) සංසිඳවන අධිකරණ","en":"(B) Issues it settles"},"h":{"si":"<div class=\"scroll\"><table><tr><th>අධිකරණය<\/th><th>ආකාරය<\/th><\/tr><tr><td><strong>අනුවාදාධිකරණය<\/strong><\/td><td><strong>සම්මුඛා විනයෙන් හා අමූළ්හවිනයෙන්<\/strong> සංසිඳේ<\/td><\/tr><\/table><\/div>","en":"<div class=\"scroll\"><table><tr><th>Issue<\/th><th>How<\/th><\/tr><tr><td><strong>accusation<\/strong><\/td><td>settled <strong>by the face-to-face verdict and the verdict of past insanity<\/strong><\/td><\/tr><\/table><\/div>"}},{"t":{"si":"(ඇ) දෙන ආකාරය","en":"(C) How it is given"},"h":{"si":"<div class=\"factors\"><div class=\"fitem\"><b>1<\/b><div>භික්ෂුව සංඝයා වෙත ගොස්, <strong>උතුරු සළුව ඒකාංශ කොට<\/strong>, <strong>වැඩිමහල් භික්ෂූන්ගේ පා වැඳ<\/strong>, <strong>උක්කුටිකව හිඳ<\/strong>, <strong>ඇඳිලි බැඳ<\/strong> — \"<strong>ස්වාමීනි, මම උමතු වීමි; උමතුවෙන් මා බොහෝ ශ්‍රමණයෙකුට නොගැළපෙන දේ කළෙමි; භික්ෂූහු මට චෝදනා කරති; අමූළ්හ වූ මම සංඝයාගෙන් අමූළ්හවිනය ඉල්ලමි<\/strong>\" යි <strong>තෙවරක්<\/strong> ඉල්ලයි.<\/div><\/div><div class=\"fitem\"><b>2<\/b><div><strong>ව්‍යක්ත, ප්‍රතිබල<\/strong> භික්ෂුවක් <strong>ඤත්තිචතුත්ථ කර්මයෙන්<\/strong> දෙයි.<\/div><\/div><\/div>","en":"<div class=\"factors\"><div class=\"fitem\"><b>1<\/b><div>The monk goes to the Saṅgha, <strong>arranges his upper robe over one shoulder<\/strong>, <strong>pays respect at the feet of the senior monks<\/strong>, <strong>squats<\/strong>, <strong>raises his joined palms<\/strong> and asks <strong>three times<\/strong>: “<strong>Venerable sirs, I was insane; in my insanity I did much that was unbecoming; the monks accuse me; being no longer deluded, I ask the Saṅgha for a verdict of past insanity.<\/strong>”<\/div><\/div><div class=\"fitem\"><b>2<\/b><div><strong>A competent, capable<\/strong> monk gives it <strong>by a motion-and-three-announcements act<\/strong>.<\/div><\/div><\/div>"}},{"t":{"si":"(ඈ) ධාර්මික හා අධාර්මික අමූළ්හවිනය දාන — චූළවග්ගය","en":"(D) Legitimate and illegitimate grants — Cūḷavagga"},"h":{"si":"<div class=\"scroll\"><table><tr><th>භික්ෂුවගේ තත්ත්වය<\/th><th>ඔහු කියන දෙය<\/th><th>විනිශ්චය<\/th><\/tr><tr><td>ඇවතකට පැමිණ, <strong>සිහි ඇතිව ම<\/strong><\/td><td>\"<strong>ඇවැත්නි, එබඳු ඇවතක් සිහි නොවේ<\/strong>\"<\/td><td><strong>අධාර්මික<\/strong><\/td><\/tr><tr><td>ඇවතකට පැමිණ, <strong>සිහි ඇතිව ම<\/strong><\/td><td>\"<strong>සිහිනයක් මෙන් සිහි වේ<\/strong>\"<\/td><td><strong>අධාර්මික<\/strong><\/td><\/tr><tr><td>ඇවතකට පැමිණ, <strong>උමතු නොවූවෙකු උමතුවකු මෙන් හැසිර<\/strong><\/td><td>\"<strong>මම ද මෙසේ කරමි, ඔබ ද මෙසේ කරති; මට ද එය වටී, ඔබට ද වටී<\/strong>\"<\/td><td><strong>අධාර්මික<\/strong><\/td><\/tr><tr><td><strong>සැබැවින් ම උමතු වූ<\/strong>, උමතුවෙන් කළ දේ <strong>සිහි නොවන<\/strong><\/td><td>\"<strong>ඇවැත්නි, එය සිහි නොවේ<\/strong>\"<\/td><td><strong>ධාර්මික<\/strong><\/td><\/tr><tr><td><strong>සැබැවින් ම උමතු වූ<\/strong>,<\/td><td>\"<strong>සිහිනයක් මෙන් සිහි වේ<\/strong>\"<\/td><td><strong>ධාර්මික<\/strong><\/td><\/tr><tr><td><strong>සැබැවින් ම උමතු වූ<\/strong>,<\/td><td>\"<strong>මම ද මෙසේ කරමි ... ඔබට ද වටී<\/strong>\" (උමතුව නිසා ම)<\/td><td><strong>ධාර්මික<\/strong><\/td><\/tr><\/table><\/div>","en":"<div class=\"scroll\"><table><tr><th>The monk’s state<\/th><th>What he says<\/th><th>Ruling<\/th><\/tr><tr><td>has committed an offence, <strong>remembering it<\/strong><\/td><td>“<strong>Friends, I don’t remember such an offence<\/strong>”<\/td><td><strong>illegitimate<\/strong><\/td><\/tr><tr><td>has committed an offence, <strong>remembering it<\/strong><\/td><td>“<strong>I remember it as in a dream<\/strong>”<\/td><td><strong>illegitimate<\/strong><\/td><\/tr><tr><td>has committed an offence, <strong>sane but acting insane<\/strong><\/td><td>“<strong>I do this, you do this; it’s allowable for me, allowable for you<\/strong>”<\/td><td><strong>illegitimate<\/strong><\/td><\/tr><tr><td><strong>really was insane<\/strong>, <strong>does not remember<\/strong> what he did<\/td><td>“<strong>Friends, I don’t remember it<\/strong>”<\/td><td><strong>legitimate<\/strong><\/td><\/tr><tr><td><strong>really was insane<\/strong><\/td><td>“<strong>I remember it as in a dream<\/strong>”<\/td><td><strong>legitimate<\/strong><\/td><\/tr><tr><td><strong>really was insane<\/strong><\/td><td>“<strong>I do this … allowable for you<\/strong>” (because of the insanity)<\/td><td><strong>legitimate<\/strong><\/td><\/tr><\/table><\/div>"}}],"as4":[{"t":{"si":"කථා වස්තුව","en":"The Story"},"h":{"si":"<div class=\"place\">සැවැත් නුවර · ජේතවනාරාමය<\/div><p><strong>ෂඩ්වර්ගීය භික්ෂූහු<\/strong> <mark>භික්ෂූන්ගේ <strong>පිළිගැනීමක් (පටිඤ්ඤාවක්) නොමැතිව<\/strong> ඔවුන්ට <strong>තජ්ජනීය, නියස්ස, පබ්බාජනීය, පටිසාරණීය, උක්ඛේපනීය<\/strong> කර්ම කළහ<\/mark>. අල්පේච්ඡ භික්ෂූහු දොස් කීහ. භාග්‍යවතුන් වහන්සේ <strong>පිළිගැනීම අනුව ම<\/strong> කටයුතු කළ යුතු බව වදාළහ.<\/p>","en":"<div class=\"place\">Sāvatthī · Jetavana monastery<\/div><p><strong>The group-of-six<\/strong> <mark>carried out <strong>censure, guidance, banishment, reconciliation and suspension<\/strong> acts against monks <strong>without their acknowledgement<\/strong><\/mark>. Monks of few wishes complained. The Blessed One taught that matters are to be dealt with <strong>according to what is acknowledged<\/strong>.<\/p>"}},{"t":{"si":"(අ) විස්තරය — කඞ්ඛාවිතරණී අනුව","en":"(A) Explanation — according to the Kaṅkhāvitaraṇī"},"h":{"si":"<p><mark>ඇවතට පැමිණි භික්ෂුවගේ <strong>\"මම මේ ඇවතට පැමිණියෙමි\"<\/strong> යන <strong>පිළිගැනීම (පටිඤ්ඤාව)<\/strong> අනුව ම <strong>කරවීම<\/strong><\/mark> — පටිඤ්ඤාතකරණය යි.<\/p><div class=\"scroll\"><table><tr><th>ඇවැත<\/th><th>පටිඤ්ඤාව<\/th><th>කරණය<\/th><\/tr><tr><td><strong>ලහුක ඇවැත්<\/strong> (පාචිත්තිය ආදිය)<\/td><td>\"<strong>ස්වාමීනි, මම අසවල් ඇවතට පැමිණියෙමි<\/strong>\" — \"<strong>දකිහි ද?<\/strong>\" — \"<strong>ඔව්, දකිමි<\/strong>\"<\/td><td>\"<strong>මතු සංවර වන්න<\/strong>\" යි කීම<\/td><\/tr><tr><td><strong>සංඝාදිසේස<\/strong><\/td><td><strong>පරිවාස ආදිය ඉල්ලීම<\/strong><\/td><td><strong>පරිවාස ආදිය දීම<\/strong><\/td><\/tr><\/table><\/div>","en":"<p><mark>Dealing with an offender <strong>according to his own acknowledgement<\/strong> — “<strong>I have committed this offence<\/strong>”<\/mark> — is acting on acknowledgement.<\/p><div class=\"scroll\"><table><tr><th>Offence<\/th><th>Acknowledgement<\/th><th>Dealing<\/th><\/tr><tr><td><strong>light offences<\/strong> (pācittiya etc.)<\/td><td>“<strong>Venerable sir, I have committed such-and-such an offence<\/strong>” — “<strong>Do you see it?<\/strong>” — “<strong>Yes, I see it<\/strong>”<\/td><td>saying, “<strong>Be restrained in future<\/strong>”<\/td><\/tr><tr><td><strong>saṅghādisesa<\/strong><\/td><td><strong>asking for probation etc.<\/strong><\/td><td><strong>giving probation etc.<\/strong><\/td><\/tr><\/table><\/div>"}},{"t":{"si":"(ආ) සංසිඳවන අධිකරණ","en":"(B) Issues it settles"},"h":{"si":"<div class=\"scroll\"><table><tr><th>අධිකරණය<\/th><th>ආකාරය<\/th><\/tr><tr><td><strong>ආපත්තාධිකරණය<\/strong><\/td><td><strong>සම්මුඛා විනයෙන් හා පටිඤ්ඤාතකරණයෙන්<\/strong> සංසිඳේ<\/td><\/tr><\/table><\/div><p><mark><strong>එක් භික්ෂුවක් ඉදිරියේ, ගණයක් ඉදිරියේ හෝ සංඝයා මැද<\/strong> ලහුක ඇවතක් දේශනා කරන විට<\/mark> ආපත්තාධිකරණය මේ සමථ දෙකෙන් සංසිඳේ.<\/p>","en":"<div class=\"scroll\"><table><tr><th>Issue<\/th><th>How<\/th><\/tr><tr><td><strong>offence<\/strong><\/td><td>settled <strong>by the face-to-face verdict and acting on acknowledgement<\/strong><\/td><\/tr><\/table><\/div><p><mark>When a light offence is confessed <strong>before one monk, before a group or in the midst of the Saṅgha<\/strong><\/mark>, the offence issue is settled by these two.<\/p>"}},{"t":{"si":"(ඇ) ඇවැත් දේශනාවේ සම්මුඛතා","en":"(C) Presence in confession"},"h":{"si":"<div class=\"scroll\"><table><tr><th>සම්මුඛතාව<\/th><th>අර්ථය<\/th><\/tr><tr><td><strong>පුග්ගල සම්මුඛතා<\/strong><\/td><td><strong>දේශනා කරන්නා හා දේශනා පිළිගන්නා<\/strong> සම්මුඛව සිටීම<\/td><\/tr><tr><td><strong>ධම්ම, විනය සම්මුඛතා<\/strong><\/td><td>ඇවැත <strong>සත්‍ය වීම<\/strong> හා <strong>නිසි ආකාරයෙන්<\/strong> දේශනා කිරීම<\/td><\/tr><tr><td><strong>සංඝ සම්මුඛතා<\/strong><\/td><td><strong>පුද්ගලයෙකු හෝ ගණයෙකු ඉදිරියේ<\/strong> දේශනා කරන විට <strong>නැත<\/strong><\/td><\/tr><\/table><\/div>","en":"<div class=\"scroll\"><table><tr><th>Presence<\/th><th>Meaning<\/th><\/tr><tr><td><strong>of the individuals<\/strong><\/td><td><strong>the one confessing and the one receiving the confession<\/strong> are present<\/td><\/tr><tr><td><strong>of the Dhamma, of the Vinaya<\/strong><\/td><td>the offence <strong>is real<\/strong> and is confessed <strong>in the proper way<\/strong><\/td><\/tr><tr><td><strong>of the Saṅgha<\/strong><\/td><td><strong>lacking<\/strong> when confessed <strong>before an individual or a group<\/strong><\/td><\/tr><\/table><\/div>"}},{"t":{"si":"(ඈ) ධාර්මික හා අධාර්මික පටිඤ්ඤාතකරණ — චූළවග්ගය","en":"(D) Legitimate and illegitimate acting on acknowledgement — Cūḷavagga"},"h":{"si":"<div class=\"scroll\"><table><tr><th>ඇවැත<\/th><th>ඔහු පිළිගන්නේ<\/th><th>කරනු ලබන්නේ<\/th><th>විනිශ්චය<\/th><\/tr><tr><td><strong>පාරාජික<\/strong><\/td><td>\"<strong>සංඝාදිසේසයකට පැමිණියෙමි<\/strong>\"<\/td><td>සංඝාදිසේසයෙන්<\/td><td><strong>අධාර්මික<\/strong><\/td><\/tr><tr><td>ඇවතකට පැමිණ<\/td><td><strong>ඒ ඇවත නොව වෙනත් ලහුක / ගරුක ඇවතක්<\/strong> පිළිගනී<\/td><td>ඔහු පිළිගත් ඇවතින්<\/td><td><strong>අධාර්මික<\/strong><\/td><\/tr><tr><td><strong>පාරාජික<\/strong><\/td><td>\"<strong>පාරාජිකයකට පැමිණියෙමි<\/strong>\"<\/td><td>පාරාජිකයෙන්<\/td><td><strong>ධාර්මික<\/strong><\/td><\/tr><tr><td>ඇවතකට පැමිණ<\/td><td><strong>ඒ ඇවත ම<\/strong> පිළිගනී<\/td><td><strong>ඒ ඇවතින් ම<\/strong><\/td><td><strong>ධාර්මික<\/strong><\/td><\/tr><\/table><\/div>","en":"<div class=\"scroll\"><table><tr><th>Offence<\/th><th>He acknowledges<\/th><th>Dealt with by<\/th><th>Ruling<\/th><\/tr><tr><td><strong>pārājika<\/strong><\/td><td>“<strong>I have committed a saṅghādisesa<\/strong>”<\/td><td>a saṅghādisesa<\/td><td><strong>illegitimate<\/strong><\/td><\/tr><tr><td>any offence<\/td><td><strong>a different offence, lighter or heavier<\/strong><\/td><td>the offence he acknowledged<\/td><td><strong>illegitimate<\/strong><\/td><\/tr><tr><td><strong>pārājika<\/strong><\/td><td>“<strong>I have committed a pārājika<\/strong>”<\/td><td>a pārājika<\/td><td><strong>legitimate<\/strong><\/td><\/tr><tr><td>any offence<\/td><td><strong>that very offence<\/strong><\/td><td><strong>that very offence<\/strong><\/td><td><strong>legitimate<\/strong><\/td><\/tr><\/table><\/div>"}}],"as5":[{"t":{"si":"කථා වස්තුව","en":"The Story"},"h":{"si":"<div class=\"place\">සැවැත් නුවර · ජේතවනාරාමය<\/div><p>භික්ෂූහු <strong>සංඝයා මැද ආරවුල්, කලහ, විවාදවලට පැමිණ<\/strong>, <mark><strong>මුඛ නැමැති ආයුධවලින් එකිනෙකා විදිමින්<\/strong><\/mark> සිටියහ; ඒ අධිකරණය සංසිඳවිය නොහැකි විය. භාග්‍යවතුන් වහන්සේ \"<strong>මහණෙනි, එබඳු අධිකරණය යේභුය්‍යසිකාවෙන් සංසිඳවීමට අනුදනිමි<\/strong>\" යි වදාරා <strong>සලාකග්ගාහාපකයෙකු<\/strong> සම්මත කිරීමට අනුදැන වදාළහ.<\/p>","en":"<div class=\"place\">Sāvatthī · Jetavana monastery<\/div><p>Monks <strong>in the midst of the Saṅgha had fallen into strife, quarrels and disputes<\/strong>, <mark><strong>stabbing one another with the weapons of their tongues<\/strong><\/mark>, and could not settle the issue. The Blessed One said, “<strong>Monks, I allow such an issue to be settled by majority decision<\/strong>,” and allowed <strong>a distributor of voting tickets<\/strong> to be authorised.<\/p>"}},{"t":{"si":"(අ) විස්තරය — කඞ්ඛාවිතරණී අනුව","en":"(A) Explanation — according to the Kaṅkhāvitaraṇī"},"h":{"si":"<p>විවාදාධිකරණය <strong>සම්මුඛා විනයෙන් පමණක්<\/strong> නොසංසිඳේ නම්, <strong>උබ්බාහිකාවට සම්මත භික්ෂූහු<\/strong> \"<strong>අපට සංසිඳවිය නොහැකිය<\/strong>\" යි <strong>සංඝයාට ම<\/strong> භාර දෙති. එවිට සංඝයා <strong>අංග පහකින් යුත්<\/strong> භික්ෂුවක් <strong>සලාකග්ගාහාපකයා<\/strong> ලෙස සම්මත කොට, ඔහු ලවා <strong>සලාක (ඡන්ද කූරු) ගන්වා<\/strong>, රැස් වූ පිරිසේ <mark><strong>ධර්මවාදීන්ගේ බහුතරය<\/strong> අනුව, <strong>ධර්මවාදීන් කියන පරිදි<\/strong><\/mark> සංසිඳවයි.<\/p><p><mark><strong>යේභුය්‍යසික කර්මය කිරීම<\/strong> — \"යේභුය්‍යසිකා\" නම් වේ<\/mark>.<\/p>","en":"<p>If a dispute is not settled <strong>by the face-to-face verdict alone<\/strong>, <strong>the monks authorised as a referral committee<\/strong> hand it back <strong>to the Saṅgha<\/strong>, saying, “<strong>We cannot settle it.<\/strong>” The Saṅgha then authorises a monk <strong>with five qualities<\/strong> as <strong>ticket distributor<\/strong>, has him <strong>distribute tickets<\/strong>, and settles it <mark>according to <strong>the majority of those who speak Dhamma<\/strong> in the assembly, <strong>as they say<\/strong><\/mark>.<\/p><p><mark><strong>Carrying out the majority-decision act<\/strong> is called “majority decision”<\/mark>.<\/p>"}},{"t":{"si":"(ආ) සංසිඳවන අධිකරණ","en":"(B) Issues it settles"},"h":{"si":"<div class=\"scroll\"><table><tr><th>අධිකරණය<\/th><th>ආකාරය<\/th><\/tr><tr><td><strong>විවාදාධිකරණය<\/strong><\/td><td><strong>සම්මුඛා විනයෙන් හා යේභුය්‍යසිකාවෙන්<\/strong> සංසිඳේ<\/td><\/tr><\/table><\/div>","en":"<div class=\"scroll\"><table><tr><th>Issue<\/th><th>How<\/th><\/tr><tr><td><strong>dispute<\/strong><\/td><td>settled <strong>by the face-to-face verdict and majority decision<\/strong><\/td><\/tr><\/table><\/div>"}},{"t":{"si":"(ඇ) සලාකග්ගාහාපක භික්ෂුවගේ අංග පහ","en":"(C) Five qualities of the ticket distributor"},"h":{"si":"<div class=\"factors\"><div class=\"fitem\"><b>1<\/b><div><strong>ඡන්දයෙන්<\/strong> අගතියට නොයන.<\/div><\/div><div class=\"fitem\"><b>2<\/b><div><strong>ද්වේෂයෙන්<\/strong> අගතියට නොයන.<\/div><\/div><div class=\"fitem\"><b>3<\/b><div><strong>මෝහයෙන්<\/strong> අගතියට නොයන.<\/div><\/div><div class=\"fitem\"><b>4<\/b><div><strong>භයෙන්<\/strong> අගතියට නොයන.<\/div><\/div><div class=\"fitem\"><b>5<\/b><div><strong>ගත් සලාක හා නොගත් සලාක<\/strong> දන්නා.<\/div><\/div><\/div><p>ඔහු <strong>ඤත්තිදුතිය කර්මයෙන්<\/strong> සම්මත කළ යුතුය.<\/p>","en":"<div class=\"factors\"><div class=\"fitem\"><b>1<\/b><div>Does not go astray <strong>through desire<\/strong>.<\/div><\/div><div class=\"fitem\"><b>2<\/b><div>Does not go astray <strong>through hatred<\/strong>.<\/div><\/div><div class=\"fitem\"><b>3<\/b><div>Does not go astray <strong>through delusion<\/strong>.<\/div><\/div><div class=\"fitem\"><b>4<\/b><div>Does not go astray <strong>through fear<\/strong>.<\/div><\/div><div class=\"fitem\"><b>5<\/b><div>Knows <strong>which tickets have been taken and which not<\/strong>.<\/div><\/div><\/div><p>He is authorised <strong>by a motion-and-one-announcement act<\/strong>.<\/p>"}},{"t":{"si":"(ඈ) සලාක ගැනීමේ ක්‍රම තුන","en":"(D) Three ways of taking tickets"},"h":{"si":"<div class=\"scroll\"><table><tr><th>ක්‍රමය<\/th><th>කරන ආකාරය<\/th><\/tr><tr><td><strong>ගූළ්හක (රහස්)<\/strong><\/td><td>සලාක දෙවර්ගය වෙන් කොට, එක් එක් භික්ෂුවට \"<strong>මෙය මෙබඳු වාදියාගේ, මෙය මෙබඳු වාදියාගේ; කැමැත්ත ගන්න<\/strong>\" යි කියා, <strong>\"කිසිවකුට නොපෙන්වන්න\"<\/strong> යි ගන්වයි. <strong>අධර්මවාදීන් බහුතර<\/strong> යැයි දැනගතහොත් <strong>\"නරක ලෙස ගත්තේය\"<\/strong> යි <strong>ආපසු ගනී<\/strong>; <strong>ධර්මවාදීන් බහුතර<\/strong> නම් <strong>\"මනාව ගත්තේය\"<\/strong> යි <strong>දන්වයි<\/strong><\/td><\/tr><tr><td><strong>සකණ්ණජප්පක (කනට කොඳුරා)<\/strong><\/td><td>එක් එක් භික්ෂුවකගේ <strong>කන ළඟ<\/strong> \"<strong>මෙය මෙබඳු වාදියාගේ සලාකය ... කැමැත්ත ගන්න; කිසිවකුට නොකියන්න<\/strong>\" යි කියයි. ඉතිරිය ගූළ්හකය මෙනි — <strong>අධර්මවාදීන් බහුතර නම් ආපසු ගනී<\/strong>, <strong>ධර්මවාදීන් බහුතර නම් දන්වයි<\/strong><\/td><\/tr><tr><td><strong>විවටක (විවෘත)<\/strong><\/td><td><strong>ධර්මවාදීන් බහුතර<\/strong> බව දන්නේ නම් <strong>විවෘතව ම<\/strong> ගන්වයි<\/td><\/tr><\/table><\/div>","en":"<div class=\"scroll\"><table><tr><th>Way<\/th><th>How it is done<\/th><\/tr><tr><td><strong>secret (gūḷhaka)<\/strong><\/td><td>separating the two kinds of ticket, he tells each monk, “<strong>This is for those who say this, this for those who say that; take whichever you like<\/strong>,” adding “<strong>Don’t show anyone<\/strong>.” If he finds <strong>those against the Dhamma are the majority<\/strong>, he <strong>takes them back<\/strong> as “<strong>badly taken<\/strong>”; if <strong>those of the Dhamma are the majority<\/strong>, he <strong>announces it<\/strong> as “<strong>well taken<\/strong>”<\/td><\/tr><tr><td><strong>whispering in the ear (sakaṇṇajappaka)<\/strong><\/td><td>he says <strong>into each monk’s ear<\/strong>, “<strong>This is the ticket for those who say this … take whichever you like; don’t tell anyone<\/strong>.” Then as with the secret way — <strong>if those against the Dhamma are the majority he takes them back<\/strong>, <strong>if those of the Dhamma are, he announces it<\/strong><\/td><\/tr><tr><td><strong>open (vivaṭaka)<\/strong><\/td><td>if he knows <strong>those of the Dhamma are the majority<\/strong>, he has the tickets taken <strong>openly<\/strong><\/td><\/tr><\/table><\/div>"}},{"t":{"si":"(ඉ) ධාර්මික හා අධාර්මික සලාක ගැනීම් — චූළවග්ගය","en":"(E) Legitimate and illegitimate ticket-taking — Cūḷavagga"},"h":{"si":"<div class=\"scroll\"><table><tr><th>අධාර්මික සලාකග්ගාහ දහය<\/th><th>ධාර්මික සලාකග්ගාහ දහය<\/th><\/tr><tr><td>අධිකරණය <strong>සුළු<\/strong> ය<\/td><td>අධිකරණය <strong>සුළු නොවේ<\/strong><\/td><\/tr><tr><td><strong>නිසි ගමනක් ගොස් නැත<\/strong> (ආවාසයෙන් ආවාසයට නොගිය)<\/td><td><strong>නිසි ගමන ගොස් ඇත<\/strong><\/td><\/tr><tr><td><strong>සිහි කරවා, සිහි කරවා නැත<\/strong><\/td><td><strong>සිහි කරවා ඇත<\/strong><\/td><\/tr><tr><td><strong>අධර්මවාදීන් බහුතර<\/strong> බව දනී<\/td><td><strong>ධර්මවාදීන් බහුතර<\/strong> බව දනී<\/td><\/tr><tr><td><strong>අධර්මවාදීන් බහුතර වෙත්වා<\/strong> යි සිතයි<\/td><td><strong>ධර්මවාදීන් බහුතර වෙත්වා<\/strong> යි සිතයි<\/td><\/tr><tr><td><strong>සංඝයා බිඳෙනු ඇතැයි<\/strong> දනී<\/td><td><strong>සංඝයා නොබිඳෙනු ඇතැයි<\/strong> දනී<\/td><\/tr><tr><td><strong>සංඝයා බිඳේවා<\/strong> යි සිතයි<\/td><td><strong>සංඝයා නොබිඳේවා<\/strong> යි සිතයි<\/td><\/tr><tr><td><strong>අධර්මයෙන්<\/strong> ගනිති<\/td><td><strong>ධර්මයෙන්<\/strong> ගනිති<\/td><\/tr><tr><td><strong>වර්ගව (අසමගිව)<\/strong> ගනිති<\/td><td><strong>සමගිව<\/strong> ගනිති<\/td><\/tr><tr><td><strong>තම දෘෂ්ටිය අනුව<\/strong> නොගනිති<\/td><td><strong>තම දෘෂ්ටිය අනුව<\/strong> ගනිති<\/td><\/tr><\/table><\/div>","en":"<div class=\"scroll\"><table><tr><th>The ten illegitimate<\/th><th>The ten legitimate<\/th><\/tr><tr><td>the issue is <strong>trivial<\/strong><\/td><td>the issue is <strong>not trivial<\/strong><\/td><\/tr><tr><td><strong>it has not gone the proper course<\/strong> (from residence to residence)<\/td><td><strong>it has gone the proper course<\/strong><\/td><\/tr><tr><td><strong>it has not been brought to mind repeatedly<\/strong><\/td><td><strong>it has been brought to mind<\/strong><\/td><\/tr><tr><td>he knows <strong>those against the Dhamma are the majority<\/strong><\/td><td>he knows <strong>those of the Dhamma are the majority<\/strong><\/td><\/tr><tr><td>he thinks “<strong>may those against the Dhamma be the majority<\/strong>”<\/td><td>he thinks “<strong>may those of the Dhamma be the majority<\/strong>”<\/td><\/tr><tr><td>he knows <strong>the Saṅgha will split<\/strong><\/td><td>he knows <strong>the Saṅgha will not split<\/strong><\/td><\/tr><tr><td>he thinks “<strong>may the Saṅgha split<\/strong>”<\/td><td>he thinks “<strong>may the Saṅgha not split<\/strong>”<\/td><\/tr><tr><td>they take them <strong>illegitimately<\/strong><\/td><td>they take them <strong>legitimately<\/strong><\/td><\/tr><tr><td>they take them <strong>as a faction<\/strong><\/td><td>they take them <strong>in unity<\/strong><\/td><\/tr><tr><td>they <strong>do not<\/strong> take them <strong>according to their view<\/strong><\/td><td>they take them <strong>according to their view<\/strong><\/td><\/tr><\/table><\/div>"}}],"as6":[{"t":{"si":"කථා වස්තුව","en":"The Story"},"h":{"si":"<div class=\"place\">සැවැත් නුවර · ජේතවනාරාමය<\/div><p><strong>උපවාළ<\/strong> නම් භික්ෂුවක් <mark>සංඝයා මැද <strong>ඇවතක් ගැන විමසද්දී<\/strong>, <strong>ප්‍රතික්ෂේප කොට පිළිගත්තේය, පිළිගෙන ප්‍රතික්ෂේප කළේය<\/strong>, <strong>එකකින් අනෙකක් වසා කථා කළේය<\/strong>, <strong>දැන දැන බොරු කීය<\/strong><\/mark>. අල්පේච්ඡ භික්ෂූහු දොස් කීහ. භාග්‍යවතුන් වහන්සේ උපවාළ භික්ෂුවට <strong>තස්සපාපියසිකා කර්මය<\/strong> කිරීමට අනුදැන වදාළහ.<\/p>","en":"<div class=\"place\">Sāvatthī · Jetavana monastery<\/div><p>A monk named <strong>Upavāḷa<\/strong>, <mark><strong>being questioned about an offence<\/strong> in the midst of the Saṅgha, <strong>denied and then admitted, admitted and then denied<\/strong>, <strong>evaded one question with another<\/strong>, and <strong>told deliberate lies<\/strong><\/mark>. Monks of few wishes complained. The Blessed One allowed <strong>a further-punishment act<\/strong> to be carried out against Upavāḷa.<\/p>"}},{"t":{"si":"(අ) විස්තරය — කඞ්ඛාවිතරණී අනුව","en":"(A) Explanation — according to the Kaṅkhāvitaraṇī"},"h":{"si":"<p><mark><strong>පාරාජිකයකින් හෝ පාරාජිකයට සමීප (සාමන්ත) ඇවතකින්<\/strong> චෝදනා ලබන, <strong>එකකින් අනෙකක් වසන<\/strong>, <strong>පව් බහුල බැවින් පාපිෂ්ඨ<\/strong> පුද්ගලයෙකුට<\/mark>, සංඝයා — \"<strong>මොහු මුල් නොසිඳුණෙක් නම්, මනාව හැසිර ඔසාරණය ලබනු ඇත; මුල් සිඳුණෙක් නම් ඔහුට ම නාසනය වනු ඇත<\/strong>\" යි සිතා — <strong>ඤත්තිචතුත්ථ කර්මයෙන්<\/strong> තස්සපාපියසිකා කර්මය කරයි.<\/p>","en":"<p><mark>For <strong>a wicked person, wicked from the abundance of his wrongdoing<\/strong>, who is accused <strong>of a pārājika or something close to a pārājika<\/strong> and <strong>evades one question with another<\/strong><\/mark>, the Saṅgha — thinking, “<strong>If his root is not cut, he will behave properly and gain reinstatement; if it is cut, he will destroy himself<\/strong>” — carries out the further-punishment act <strong>by a motion-and-three-announcements act<\/strong>.<\/p>"}},{"t":{"si":"(ආ) සංසිඳවන අධිකරණ","en":"(B) Issues it settles"},"h":{"si":"<div class=\"scroll\"><table><tr><th>අධිකරණය<\/th><th>ආකාරය<\/th><\/tr><tr><td><strong>අනුවාදාධිකරණය<\/strong><\/td><td><strong>සම්මුඛා විනයෙන් හා තස්සපාපියසිකාවෙන්<\/strong> සංසිඳේ<\/td><\/tr><\/table><\/div>","en":"<div class=\"scroll\"><table><tr><th>Issue<\/th><th>How<\/th><\/tr><tr><td><strong>accusation<\/strong><\/td><td>settled <strong>by the face-to-face verdict and further punishment<\/strong><\/td><\/tr><\/table><\/div>"}},{"t":{"si":"(ඇ) ධාර්මිකව කිරීමේ අංග පහ","en":"(C) Five factors for doing it legitimately"},"h":{"si":"<div class=\"factors\"><div class=\"fitem\"><b>1<\/b><div><strong>අපිරිසිදු<\/strong> ය.<\/div><\/div><div class=\"fitem\"><b>2<\/b><div><strong>ලජ්ජා නැති<\/strong> ය.<\/div><\/div><div class=\"fitem\"><b>3<\/b><div><strong>චෝදනා සහිත<\/strong> ය.<\/div><\/div><div class=\"fitem\"><b>4<\/b><div>සංඝයා <strong>ධර්මයෙන්<\/strong> කරයි.<\/div><\/div><div class=\"fitem\"><b>5<\/b><div>සංඝයා <strong>සමගිව<\/strong> කරයි.<\/div><\/div><\/div>","en":"<div class=\"factors\"><div class=\"fitem\"><b>1<\/b><div>He is <strong>impure<\/strong>.<\/div><\/div><div class=\"fitem\"><b>2<\/b><div>He is <strong>shameless<\/strong>.<\/div><\/div><div class=\"fitem\"><b>3<\/b><div>He is <strong>under accusation<\/strong>.<\/div><\/div><div class=\"fitem\"><b>4<\/b><div>The Saṅgha does it <strong>legitimately<\/strong>.<\/div><\/div><div class=\"fitem\"><b>5<\/b><div>The Saṅgha does it <strong>in unity<\/strong>.<\/div><\/div><\/div>"}},{"t":{"si":"(ඈ) ධාර්මික හා අධාර්මික කර්ම","en":"(D) Legitimate and illegitimate acts"},"h":{"si":"<div class=\"scroll\"><table><tr><th>අධාර්මික කර්මය (අංග තුනෙන් යුත්)<\/th><th>ධාර්මික කර්මය (අංග තුනෙන් යුත්)<\/th><\/tr><tr><td><strong>අසම්මුඛව<\/strong> කළ<\/td><td><strong>සම්මුඛව<\/strong> කළ<\/td><\/tr><tr><td><strong>නොවිමසා<\/strong> කළ<\/td><td><strong>විමසා<\/strong> කළ<\/td><\/tr><tr><td><strong>පිළිගැනීමක් නැතිව<\/strong> කළ<\/td><td><strong>පිළිගැනීමෙන්<\/strong> කළ<\/td><\/tr><tr><td><strong>ඇවතක් නැති<\/strong> අයට කළ<\/td><td><strong>ඇවතක් ඇති<\/strong> අයට කළ<\/td><\/tr><tr><td><strong>දේශනා කළ යුතු නොවන<\/strong> ඇවතකට කළ<\/td><td><strong>දේශනා කළ යුතු<\/strong> ඇවතකට කළ<\/td><\/tr><tr><td><strong>දේශනා කළ<\/strong> ඇවතකට කළ<\/td><td><strong>දේශනා නොකළ<\/strong> ඇවතකට කළ<\/td><\/tr><tr><td><strong>චෝදනා නොකොට<\/strong> කළ<\/td><td><strong>චෝදනා කොට<\/strong> කළ<\/td><\/tr><tr><td><strong>සිහි නොකරවා<\/strong> කළ<\/td><td><strong>සිහි කරවා<\/strong> කළ<\/td><\/tr><tr><td><strong>ඇවත නොනංවා<\/strong> කළ<\/td><td><strong>ඇවත නංවා<\/strong> කළ<\/td><\/tr><tr><td><strong>අධර්මයෙන්<\/strong> කළ<\/td><td><strong>ධර්මයෙන්<\/strong> කළ<\/td><\/tr><tr><td><strong>වර්ගව<\/strong> කළ<\/td><td><strong>සමගිව<\/strong> කළ<\/td><\/tr><\/table><\/div>","en":"<div class=\"scroll\"><table><tr><th>Illegitimate (with three factors)<\/th><th>Legitimate (with three factors)<\/th><\/tr><tr><td>done <strong>in his absence<\/strong><\/td><td>done <strong>in his presence<\/strong><\/td><\/tr><tr><td>done <strong>without questioning<\/strong><\/td><td>done <strong>after questioning<\/strong><\/td><\/tr><tr><td>done <strong>without acknowledgement<\/strong><\/td><td>done <strong>with acknowledgement<\/strong><\/td><\/tr><tr><td>done to one <strong>without an offence<\/strong><\/td><td>done to one <strong>with an offence<\/strong><\/td><\/tr><tr><td>for an offence <strong>not to be confessed<\/strong><\/td><td>for an offence <strong>to be confessed<\/strong><\/td><\/tr><tr><td>for an offence <strong>already confessed<\/strong><\/td><td>for an offence <strong>not yet confessed<\/strong><\/td><\/tr><tr><td>done <strong>without accusing<\/strong><\/td><td>done <strong>after accusing<\/strong><\/td><\/tr><tr><td>done <strong>without reminding<\/strong><\/td><td>done <strong>after reminding<\/strong><\/td><\/tr><tr><td>done <strong>without charging the offence<\/strong><\/td><td>done <strong>after charging the offence<\/strong><\/td><\/tr><tr><td>done <strong>illegitimately<\/strong><\/td><td>done <strong>legitimately<\/strong><\/td><\/tr><tr><td>done <strong>as a faction<\/strong><\/td><td>done <strong>in unity<\/strong><\/td><\/tr><\/table><\/div>"}},{"t":{"si":"(ඉ) කැමති නම් කළ හැකි අය — අංග තුන","en":"(E) Whom the Saṅgha may act against if it wishes — three factors"},"h":{"si":"<div class=\"factors\"><div class=\"fitem\"><b>1<\/b><div><strong>ආරවුල්, කලහ, විවාද, වාද<\/strong> කරන, සංඝයා තුළ <strong>අධිකරණ<\/strong> උපදවන්නා.<\/div><\/div><div class=\"fitem\"><b>2<\/b><div><strong>බාල, අව්‍යක්ත, ඇවැත් බහුල, සීමාවක් නැති<\/strong> (අනපදාන) තැනැත්තා.<\/div><\/div><div class=\"fitem\"><b>3<\/b><div><strong>නුසුදුසු ගිහි සංසර්ගයෙන්<\/strong> ගිහියන් හා මිශ්‍රව වසන්නා.<\/div><\/div><\/div>","en":"<div class=\"factors\"><div class=\"fitem\"><b>1<\/b><div>One who <strong>makes strife, quarrels, disputes and contention<\/strong>, raising <strong>issues<\/strong> in the Saṅgha.<\/div><\/div><div class=\"fitem\"><b>2<\/b><div>One who is <strong>foolish, incompetent, full of offences, without limit<\/strong>.<\/div><\/div><div class=\"fitem\"><b>3<\/b><div>One who lives <strong>in unsuitable association with householders<\/strong>.<\/div><\/div><\/div>"}},{"t":{"si":"(ඊ) කර්මය කළ භික්ෂුවගේ වත් දහඅට","en":"(F) The eighteen duties of one subjected to the act"},"h":{"si":"<div class=\"factors\"><div class=\"fitem\"><b>1<\/b><div><strong>උපසම්පදා<\/strong> නොකළ යුතුය.<\/div><\/div><div class=\"fitem\"><b>2<\/b><div><strong>නිස්සය<\/strong> නොදිය යුතුය.<\/div><\/div><div class=\"fitem\"><b>3<\/b><div><strong>සාමණේරයෙකු<\/strong> උපස්ථානයට නොගත යුතුය.<\/div><\/div><div class=\"fitem\"><b>4<\/b><div><strong>භික්ෂුණී ඔවාදක සම්මුතිය<\/strong> නොඉවසිය යුතුය.<\/div><\/div><div class=\"fitem\"><b>5<\/b><div>සම්මත වුව ද <strong>භික්ෂුණීන්ට අවවාද<\/strong> නොකළ යුතුය.<\/div><\/div><div class=\"fitem\"><b>6<\/b><div>යම් ඇවතක් නිසා කර්මය කළේ ද <strong>ඒ ඇවතට<\/strong> නොපැමිණිය යුතුය.<\/div><\/div><div class=\"fitem\"><b>7<\/b><div><strong>එබඳු වෙනත්<\/strong> ඇවතකට නොපැමිණිය යුතුය.<\/div><\/div><div class=\"fitem\"><b>8<\/b><div><strong>ඊට වඩා නරක<\/strong> ඇවතකට නොපැමිණිය යුතුය.<\/div><\/div><div class=\"fitem\"><b>9<\/b><div><strong>කර්මයට<\/strong> නොගැරහිය යුතුය.<\/div><\/div><div class=\"fitem\"><b>10<\/b><div><strong>කර්මය කළවුන්ට<\/strong> නොගැරහිය යුතුය.<\/div><\/div><div class=\"fitem\"><b>11<\/b><div><strong>ප්‍රකෘති භික්ෂුවකගේ උපෝසථය<\/strong> නොනැවැත්විය යුතුය.<\/div><\/div><div class=\"fitem\"><b>12<\/b><div><strong>පවාරණය<\/strong> නොනැවැත්විය යුතුය.<\/div><\/div><div class=\"fitem\"><b>13<\/b><div><strong>අණ කිරීමක් (සවචනීය)<\/strong> නොකළ යුතුය.<\/div><\/div><div class=\"fitem\"><b>14<\/b><div><strong>අනුවාදය (චෝදනාවට මූලිකත්වය)<\/strong> නොගත යුතුය.<\/div><\/div><div class=\"fitem\"><b>15<\/b><div><strong>අවසර<\/strong> නොගන්වා යුතුය (ඕකාසං න කාරෙතබ්බං).<\/div><\/div><div class=\"fitem\"><b>16<\/b><div><strong>චෝදනා<\/strong> නොකළ යුතුය.<\/div><\/div><div class=\"fitem\"><b>17<\/b><div><strong>සිහි<\/strong> නොකරවිය යුතුය.<\/div><\/div><div class=\"fitem\"><b>18<\/b><div><strong>භික්ෂූන් හා ආරවුල් ඇති<\/strong> නොකළ යුතුය.<\/div><\/div><\/div>","en":"<div class=\"factors\"><div class=\"fitem\"><b>1<\/b><div>He should not <strong>give full ordination<\/strong>.<\/div><\/div><div class=\"fitem\"><b>2<\/b><div>He should not <strong>give dependence<\/strong>.<\/div><\/div><div class=\"fitem\"><b>3<\/b><div>He should not <strong>have a novice attend on him<\/strong>.<\/div><\/div><div class=\"fitem\"><b>4<\/b><div>He should not <strong>accept authorisation to admonish nuns<\/strong>.<\/div><\/div><div class=\"fitem\"><b>5<\/b><div>Even if authorised, he should not <strong>admonish nuns<\/strong>.<\/div><\/div><div class=\"fitem\"><b>6<\/b><div>He should not commit <strong>the offence for which the act was done<\/strong>.<\/div><\/div><div class=\"fitem\"><b>7<\/b><div>He should not commit <strong>a similar offence<\/strong>.<\/div><\/div><div class=\"fitem\"><b>8<\/b><div>He should not commit <strong>a worse one<\/strong>.<\/div><\/div><div class=\"fitem\"><b>9<\/b><div>He should not <strong>criticise the act<\/strong>.<\/div><\/div><div class=\"fitem\"><b>10<\/b><div>He should not <strong>criticise those who did the act<\/strong>.<\/div><\/div><div class=\"fitem\"><b>11<\/b><div>He should not <strong>cancel a regular monk’s Uposatha<\/strong>.<\/div><\/div><div class=\"fitem\"><b>12<\/b><div>He should not <strong>cancel his Pavāraṇā<\/strong>.<\/div><\/div><div class=\"fitem\"><b>13<\/b><div>He should not <strong>give orders<\/strong>.<\/div><\/div><div class=\"fitem\"><b>14<\/b><div>He should not <strong>take the lead in accusing<\/strong>.<\/div><\/div><div class=\"fitem\"><b>15<\/b><div>He should not <strong>ask leave (to accuse)<\/strong>.<\/div><\/div><div class=\"fitem\"><b>16<\/b><div>He should not <strong>accuse<\/strong>.<\/div><\/div><div class=\"fitem\"><b>17<\/b><div>He should not <strong>remind (of an offence)<\/strong>.<\/div><\/div><div class=\"fitem\"><b>18<\/b><div>He should not <strong>make monks quarrel<\/strong>.<\/div><\/div><\/div>"}},{"t":{"si":"(උ) කර්මයේ අරමුණ","en":"(G) The purpose of the act"},"h":{"si":"<p><mark><strong>මුල් නොසිඳුණෙක්<\/strong> නම් මනාව හැසිර <strong>ඔසාරණය<\/strong> (කර්මයෙන් නිදහස් කිරීම) ලබයි; <strong>මුල් සිඳුණෙක් (පාරාජිකයෙක්)<\/strong> නම් <strong>ඔහුට ම නාසනය<\/strong> වේ<\/mark> (කඞ්ඛාවිතරණී).<\/p>","en":"<p><mark>If <strong>his root is not cut<\/strong>, he behaves properly and gains <strong>reinstatement<\/strong>; if <strong>his root is cut (a pārājika)<\/strong>, <strong>he destroys himself<\/strong><\/mark> (Kaṅkhāvitaraṇī).<\/p>"}}],"as7":[{"t":{"si":"කථා වස්තුව","en":"The Story"},"h":{"si":"<div class=\"place\">සැවැත් නුවර · ජේතවනාරාමය<\/div><p><strong>ආරවුල්, කලහ, විවාදවලට පැමිණ<\/strong> වාසය කළ භික්ෂූන් විසින් <mark><strong>ශ්‍රමණයෙකුට නොගැළපෙන බොහෝ දේ කියන ලදී, කරන ලදී<\/strong><\/mark>. පසුව ඔවුන්ට මෙසේ සිතිණ: \"<strong>අපි මේ ඇවැත්වලින් එකිනෙකා ලවා කරවන්නෙමු නම්, ඒ අධිකරණය දරුණු බවට, කර්කශ බවට, භේදයට හේතු විය හැකිය; අප කුමක් කළ යුතු ද?<\/strong>\" භාග්‍යවතුන් වහන්සේ <strong>තිණවත්ථාරකයෙන්<\/strong> එබඳු අධිකරණය සංසිඳවීමට අනුදැන වදාළහ.<\/p>","en":"<div class=\"place\">Sāvatthī · Jetavana monastery<\/div><p>While monks <strong>lived in strife, quarrels and disputes<\/strong>, <mark><strong>much unbecoming to ascetics was said and done<\/strong><\/mark>. Later they thought: “<strong>If we make one another answer for these offences, the issue may lead to harshness, violence and schism; what should we do?<\/strong>” The Blessed One allowed such an issue to be settled <strong>by covering over with grass<\/strong>.<\/p>"}},{"t":{"si":"(අ) විස්තරය — කඞ්ඛාවිතරණී අනුව","en":"(A) Explanation — according to the Kaṅkhāvitaraṇī"},"h":{"si":"<p><mark><strong>දෙපක්ෂයට බෙදී ආරවුල් කළ<\/strong> භික්ෂූහු <strong>බොහෝ ශ්‍රමණයෙකුට නොගැළපෙන හැසිරීම්<\/strong> කොට, පසුව <strong>ලැජ්ජා ධර්මය උපන්<\/strong> කල්හි<\/mark>, එකිනෙකා ලවා ඇවැත් කරවීමේ <strong>දෝෂය<\/strong> දැක තිණවත්ථාරක කර්මය කරති.<\/p><p><strong>\"තිණවත්ථාරක\"<\/strong> — <mark><strong>අසූචියක් තණකොළයෙන් වසා දමන්නාක් මෙන්<\/strong><\/mark> ඇවැත් <strong>එකවර වසා<\/strong> සංසිඳවීම.<\/p>","en":"<p><mark>Monks <strong>split into two factions and quarrelling<\/strong> did <strong>much unbecoming conduct<\/strong>; later, <strong>when a sense of shame arose<\/strong><\/mark>, seeing <strong>the danger<\/strong> of making one another answer for the offences, they carry out the covering-over-with-grass act.<\/p><p><strong>“Tiṇavatthāraka”<\/strong> — settling by <mark><strong>covering the offences all at once, as one covers filth with grass<\/strong><\/mark>.<\/p>"}},{"t":{"si":"(ආ) සංසිඳවන අධිකරණ","en":"(B) Issues it settles"},"h":{"si":"<div class=\"scroll\"><table><tr><th>අධිකරණය<\/th><th>ආකාරය<\/th><\/tr><tr><td><strong>ආපත්තාධිකරණය<\/strong><\/td><td><strong>සම්මුඛා විනයෙන් හා තිණවත්ථාරකයෙන්<\/strong> සංසිඳේ<\/td><\/tr><\/table><\/div>","en":"<div class=\"scroll\"><table><tr><th>Issue<\/th><th>How<\/th><\/tr><tr><td><strong>offence<\/strong><\/td><td>settled <strong>by the face-to-face verdict and covering over with grass<\/strong><\/td><\/tr><\/table><\/div>"}},{"t":{"si":"(ඇ) කරන ආකාරය — චූළවග්ගය","en":"(C) How it is done — Cūḷavagga"},"h":{"si":"<div class=\"factors\"><div class=\"fitem\"><b>1<\/b><div><strong>සියල්ලන් ම එක් තැනක රැස්<\/strong> විය යුතුය.<\/div><\/div><div class=\"fitem\"><b>2<\/b><div><strong>ව්‍යක්ත, ප්‍රතිබල<\/strong> භික්ෂුවක් <strong>සංඝයාට<\/strong> ඤත්තියක් තබයි: \"<strong>අප ආරවුල් කරද්දී බොහෝ නොගැළපෙන දේ කළෙමු... සංඝයාට සුදුසු නම්, සංඝයා මේ අධිකරණය තිණවත්ථාරකයෙන් සංසිඳවන්නේය — ථුල්ලවජ්ජ හා ගිහි සම්බන්ධ ඇවැත් හැර.<\/strong>\"<\/div><\/div><div class=\"fitem\"><b>3<\/b><div><strong>එක් එක් පක්ෂයේ<\/strong> ව්‍යක්ත භික්ෂුවක් <strong>තම පක්ෂයට<\/strong> දන්වයි: \"<strong>ආයුෂ්මතුනි, ඔබට සුදුසු නම්, ඔබගේ ද මාගේ ද ඇවැත්, ඔබගේ ද මාගේ ද යහපත පිණිස, සංඝයා මැද තිණවත්ථාරකයෙන් දෙසන්නෙමි — ථුල්ලවජ්ජ හා ගිහි සම්බන්ධ ඇවැත් හැර.<\/strong>\"<\/div><\/div><div class=\"fitem\"><b>4<\/b><div>ඉන්පසු ඔහු <strong>සංඝයාට ඤත්තිදුතිය කර්මයෙන්<\/strong> දන්වා දෙසයි; \"<strong>අපගේ මේ ඇවැත් සංඝයා මැද තිණවත්ථාරකයෙන් දෙසන ලදී<\/strong>\" යි ධාරණය කරයි.<\/div><\/div><div class=\"fitem\"><b>5<\/b><div><strong>අනෙක් පක්ෂය ද<\/strong> එසේ ම කරයි.<\/div><\/div><\/div>","en":"<div class=\"factors\"><div class=\"fitem\"><b>1<\/b><div><strong>All must assemble in one place<\/strong>.<\/div><\/div><div class=\"fitem\"><b>2<\/b><div><strong>A competent, capable<\/strong> monk sets a motion <strong>before the Saṅgha<\/strong>: “<strong>While quarrelling we did much that was unbecoming… if it is fitting for the Saṅgha, let it settle this issue by covering over with grass — except for grave faults and those connected with householders.<\/strong>”<\/div><\/div><div class=\"fitem\"><b>3<\/b><div>A competent monk <strong>of each faction<\/strong> informs <strong>his own faction<\/strong>: “<strong>Venerables, if it suits you, I will confess in the midst of the Saṅgha, by covering over with grass, your offences and mine, for your good and mine — except grave faults and those connected with householders.<\/strong>”<\/div><\/div><div class=\"fitem\"><b>4<\/b><div>He then informs the Saṅgha <strong>by a motion-and-one-announcement act<\/strong> and confesses; it is recorded: “<strong>These offences of ours have been confessed in the midst of the Saṅgha by covering over with grass.<\/strong>”<\/div><\/div><div class=\"fitem\"><b>5<\/b><div><strong>The other faction<\/strong> does the same.<\/div><\/div><\/div>"}},{"t":{"si":"(ඈ) නොමිදෙන දේ","en":"(D) What is not released"},"h":{"si":"<div class=\"scroll\"><table><tr><th>නොමිදෙන ඇවැත් / පුද්ගලයන්<\/th><th>හේතුව<\/th><\/tr><tr><td><strong>ථුල්ලවජ්ජ<\/strong> — <strong>පාරාජික, සංඝාදිසේස<\/strong> වැනි <strong>බරපතල<\/strong> ඇවැත්<\/td><td>තිණවත්ථාරකයෙන් නොවසේ<\/td><\/tr><tr><td><strong>ගිහි සම්බන්ධ<\/strong> — ගිහියන්ට නින්දා කිරීම ආදී ඇවැත්<\/td><td>තිණවත්ථාරකයෙන් නොවසේ<\/td><\/tr><tr><td><strong>දිට්ඨාවිකම්ම<\/strong> කළ අය — \"<strong>මෙය මට නොරුචිය<\/strong>\" යි <strong>විරුද්ධත්වය පළ කළ<\/strong> අය<\/td><td>ඔවුන්ගේ ඇවැත් නොමිදේ<\/td><\/tr><tr><td><strong>එහි නොසිටි<\/strong> අය<\/td><td>ඔවුන්ගේ ඇවැත් නොමිදේ<\/td><\/tr><\/table><\/div><p><mark><strong>හත්ථපාසයට පැමිණ<\/strong> \"<strong>මෙය මට නොරුචිය<\/strong>\" යි විරුද්ධත්වය පළ නොකළ සියල්ලන්ගේ — <strong>නින්දට ගිය අයගේ පවා<\/strong> — <strong>ථුල්ලවජ්ජ හා ගිහි සම්බන්ධ ඇවැත් හැර සියලු ඇවැත්<\/strong> නැගිටෙයි<\/mark> (කඞ්ඛාවිතරණී).<\/p>","en":"<div class=\"scroll\"><table><tr><th>Offences / persons not released<\/th><th>Why<\/th><\/tr><tr><td><strong>grave faults (thullavajja)<\/strong> — <strong>heavy<\/strong> offences such as <strong>pārājika and saṅghādisesa<\/strong><\/td><td>not covered by this act<\/td><\/tr><tr><td><strong>connected with householders<\/strong> — offences such as reviling laypeople<\/td><td>not covered by this act<\/td><\/tr><tr><td>those who <strong>voiced dissent<\/strong> — “<strong>This does not please me<\/strong>”<\/td><td>their offences are not released<\/td><\/tr><tr><td>those <strong>not present<\/strong><\/td><td>their offences are not released<\/td><\/tr><\/table><\/div><p><mark>For all <strong>within arm’s reach<\/strong> who did not voice dissent — <strong>even those who have fallen asleep<\/strong> — <strong>all offences except grave faults and those connected with householders<\/strong> are cleared<\/mark> (Kaṅkhāvitaraṇī).<\/p>"}},{"t":{"si":"(ඉ) අධිකරණ හා සමථ — සම්පූර්ණ සාරාංශය","en":"(E) Issues and settlements — full summary"},"h":{"si":"<div class=\"scroll\"><table><tr><th>අධිකරණය<\/th><th>සංසිඳවන සමථ<\/th><\/tr><tr><td><strong>විවාදාධිකරණය<\/strong><\/td><td><strong>දෙකකින්<\/strong> — සම්මුඛා විනය, යේභුය්‍යසිකා<\/td><\/tr><tr><td><strong>අනුවාදාධිකරණය<\/strong><\/td><td><strong>සතරකින්<\/strong> — සම්මුඛා විනය, සති විනය, අමූළ්හ විනය, තස්සපාපියසිකා<\/td><\/tr><tr><td><strong>ආපත්තාධිකරණය<\/strong><\/td><td><strong>තුනකින්<\/strong> — සම්මුඛා විනය, පටිඤ්ඤාතකරණය, තිණවත්ථාරකය<\/td><\/tr><tr><td><strong>කිච්චාධිකරණය<\/strong><\/td><td><strong>එකකින්<\/strong> — සම්මුඛා විනය පමණි<\/td><\/tr><\/table><\/div>","en":"<div class=\"scroll\"><table><tr><th>Issue<\/th><th>Settled by<\/th><\/tr><tr><td><strong>dispute<\/strong><\/td><td><strong>two<\/strong> — face-to-face verdict, majority decision<\/td><\/tr><tr><td><strong>accusation<\/strong><\/td><td><strong>four<\/strong> — face-to-face verdict, verdict of mindfulness, verdict of past insanity, further punishment<\/td><\/tr><tr><td><strong>offence<\/strong><\/td><td><strong>three<\/strong> — face-to-face verdict, acting on acknowledgement, covering over with grass<\/td><\/tr><tr><td><strong>duty<\/strong><\/td><td><strong>one<\/strong> — the face-to-face verdict alone<\/td><\/tr><\/table><\/div>"}},{"t":{"si":"(ඊ) ප්‍රාතිමෝක්ෂ නිගමනය","en":"(F) The conclusion of the Pātimokkha"},"h":{"si":"<p><strong>\"කච්චිත්ථ පරිසුද්ධා\"<\/strong> — \"<strong>මේ සමථ සතෙහි ඔබ පිරිසිදු ද? සමථවලින් සංසිඳවිය යුතු කිසිවක් ඔබට නැද්ද?<\/strong>\" යි ඇසීමයි; මෙයින් <strong>සියලු ඇවැත්වලින් පිරිසිදු බව<\/strong> අසනු ලැබේ.<\/p><p><strong>\"එත්තකං ... සික්ඛිතබ්බං\"<\/strong> — \"<strong>භාග්‍යවතුන් වහන්සේගේ සූත්‍රයෙහි (ප්‍රාතිමෝක්ෂයෙහි) ආ, එහි ඇතුළත්, අඩ මසක් පාසා උද්දේශයට එන මෙපමණ ශික්ෂාපද — කයින් සමගිව, සිතින් සතුටුව, විවාද නොකරමින් හික්මිය යුතුය<\/strong>\" — ඒ ඒ ශික්ෂාපදය <strong>නොඉක්මවා අධිසීල ශික්ෂාව සම්පූර්ණ කළ යුතුය<\/strong> (කඞ්ඛාවිතරණී).<\/p>","en":"<p><strong>“Kaccittha parisuddhā”<\/strong> — asks, “<strong>Are you pure in these seven settlements? Is there nothing of yours to be settled by them?<\/strong>”; by this <strong>purity from all offences<\/strong> is asked.<\/p><p><strong>“Ettakaṃ … sikkhitabbaṃ”<\/strong> — “<strong>This much of the training — handed down in the Blessed One’s text (the Pātimokkha), included in it, coming up for recitation every half-month — is to be trained in, united in body, rejoicing in mind, without dispute<\/strong>” — <strong>not transgressing each rule, the training in higher virtue is to be fulfilled<\/strong> (Kaṅkhāvitaraṇī).<\/p>"}}]}]);
